def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/biomedical/input/1-s2.0-S0092867420301070-mmc3.xlsx'
    xl = pd.ExcelFile(path)
    return pd.DataFrame({'sheet_name': xl.sheet_names})

def process(acetyl) -> pd.DataFrame:
    import pandas as pd
    # Sheet appears to be a single-column list of significant genes; column header may itself be a gene.
    genes = []
    # include column names that look like gene symbols
    for c in acetyl.columns:
        if pd.notna(c) and str(c).strip() != '':
            genes.append(str(c).strip())
    # include all cell values
    for c in acetyl.columns:
        genes.extend([str(x).strip() for x in acetyl[c].dropna().tolist() if str(x).strip() != ''])
    genes = pd.Series(genes).drop_duplicates().sort_values().reset_index(drop=True)
    return pd.DataFrame({'gene': genes, 'is_significant_acetylproteomics': True})

def process(acetyl_genes):
    # Count distinct significant genes (each row is a unique gene)
    return acetyl_genes[['gene']].drop_duplicates().assign(count=1).iloc[[0]][['count']].assign(count=len(acetyl_genes[['gene']].drop_duplicates()))
